"""Monitoring helpers for fleet qualification results."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Literal

from pydantic import BaseModel, ValidationError

from airbyte_agent_sdk.validation.qualification import QualificationResult

QUALIFICATION_ISSUE_MARKER = "[connector-qualification]"


class QualificationAggregateEntry(BaseModel):
    """One entry in the fleet runner's aggregate output."""

    connector_name: str
    status: Literal["evaluated", "skipped", "failed"]
    claimed_status: str | None = None
    result: QualificationResult | None = None
    error: str | None = None


class QualificationGateFailure(BaseModel):
    """One evaluated Gate failure from an aggregate report."""

    connector_name: str
    criterion: str
    claimed_status: str
    observed: object
    threshold: object
    detail: str

    @property
    def key(self) -> str:
        """Return the durable connector/criterion identity."""
        return f"{self.connector_name}:{self.criterion}"


class QualificationIssue(BaseModel):
    """An existing GitHub issue used for qualification state."""

    number: int
    title: str
    state: Literal["OPEN", "CLOSED"]


@dataclass(frozen=True)
class FailureTransitions:
    """Issue and notification transitions for one aggregate run."""

    new: tuple[str, ...]
    reappeared: tuple[str, ...]
    recovered: tuple[str, ...]
    persistent: tuple[str, ...]


def load_aggregate(path: Path) -> list[QualificationAggregateEntry]:
    """Load and validate a fleet aggregate JSON file."""
    if not path.is_file():
        raise ValueError(f"aggregate JSON does not exist: {path}")
    try:
        payload = json.loads(path.read_text())
        if not isinstance(payload, list):
            raise ValueError("aggregate JSON must be an array")
        return [QualificationAggregateEntry.model_validate(item) for item in payload]
    except (OSError, json.JSONDecodeError, ValidationError) as error:
        raise ValueError(f"invalid aggregate JSON: {error}") from error


def gate_failures(entries: list[QualificationAggregateEntry]) -> list[QualificationGateFailure]:
    """Extract evaluated Gate failures, including candidate failures."""
    failures: list[QualificationGateFailure] = []
    for entry in entries:
        if entry.status != "evaluated" or entry.result is None:
            continue
        for criterion in entry.result.criteria:
            if criterion.kind != "gate" or not criterion.evaluated or criterion.passed:
                continue
            failures.append(
                QualificationGateFailure(
                    connector_name=entry.connector_name,
                    criterion=criterion.id,
                    claimed_status=entry.claimed_status or entry.result.claimed_status.value,
                    observed=criterion.observed,
                    threshold=criterion.threshold,
                    detail=criterion.detail,
                )
            )
    return failures


def failure_transitions(
    current: set[str],
    open_failures: set[str],
    closed_failures: set[str],
    evaluated_connectors: set[str],
    unevaluated_keys: set[str],
) -> FailureTransitions:
    """Classify issue transitions, recovering only keys actually evaluated this run."""
    known_evaluated = {
        key for key in open_failures | closed_failures if key.partition(":")[0] in evaluated_connectors and key not in unevaluated_keys
    }
    return FailureTransitions(
        new=tuple(sorted(current - open_failures - closed_failures)),
        reappeared=tuple(sorted(current & closed_failures)),
        recovered=tuple(sorted(known_evaluated - current)),
        persistent=tuple(sorted(current & open_failures)),
    )


def issue_title(failure: QualificationGateFailure) -> str:
    """Build the deterministic issue title."""
    return f"{QUALIFICATION_ISSUE_MARKER} {failure.connector_name} {failure.criterion}"


def _issue_key(title: str) -> str | None:
    """Extract a connector/criterion key from a qualification issue title."""
    prefix, separator, suffix = title.partition(" ")
    if prefix != QUALIFICATION_ISSUE_MARKER or not separator:
        return None
    parts = suffix.split()
    if len(parts) != 2 or not parts[1].startswith("C"):
        return None
    return f"{parts[0]}:{parts[1]}"


class QualificationIssuePlan(BaseModel):
    """Actions and notifications for one qualification run."""

    failures: list[QualificationGateFailure]
    create: list[QualificationGateFailure]
    reopen: list[QualificationIssue]
    close: list[QualificationIssue]
    message_text: str


def build_issue_plan(
    entries: list[QualificationAggregateEntry],
    issues: list[QualificationIssue],
) -> QualificationIssuePlan:
    """Build issue actions from aggregate results and current issue state."""
    failures = gate_failures(entries)
    failures_by_key = {failure.key: failure for failure in failures}
    issues_by_key = {key: issue for issue in issues if (key := _issue_key(issue.title)) is not None}
    open_keys = {key for key, issue in issues_by_key.items() if issue.state == "OPEN"}
    closed_keys = {key for key, issue in issues_by_key.items() if issue.state == "CLOSED"}
    evaluated_connectors = {entry.connector_name for entry in entries if entry.status == "evaluated"}
    unevaluated_keys = {
        f"{entry.connector_name}:{criterion}" for entry in entries if entry.result is not None for criterion in entry.result.unevaluated_criteria
    }
    transitions = failure_transitions(
        set(failures_by_key),
        open_keys,
        closed_keys,
        evaluated_connectors,
        unevaluated_keys,
    )
    create = [failures_by_key[key] for key in transitions.new]
    reopen = [issues_by_key[key] for key in transitions.reappeared]
    close = [issues_by_key[key] for key in transitions.recovered if key in open_keys]
    messages = [
        *(f"New qualification failure: {failure.key}" for failure in create),
        *(f"Qualification failure reappeared: {_issue_key(issue.title)}" for issue in reopen),
        *(f"Qualification failure recovered: {_issue_key(issue.title)}" for issue in close),
    ]
    return QualificationIssuePlan(
        failures=failures,
        create=create,
        reopen=reopen,
        close=close,
        message_text="\n".join(messages),
    )

"""AWS Secrets Manager hydration for executable bundles (opt-in `secrets-aws` extra).

This module is only reached on the opt-in local execution path -- when
`SECRETS_CONFIGURED_FROM_ENVIRONMENT=true`, the SDK calls
`POST /connectors/{id}/execute/prepare` and resolves the returned bundle's
unhydrated `secret_coordinate::` values against the customer's own AWS Secrets
Manager in their data plane. `boto3` is imported lazily inside
`hydrate_source_config` so the base install (without the `secrets-aws`
extra) never imports boto3 on the hosted path.
"""

from __future__ import annotations

import json
from typing import Any

from airbyte_agent_sdk.config import AWSDataPlaneCredentials, resolve_aws_credentials

_SECRET_COORDINATE_PREFIX = "secret_coordinate::"

_INSTALL_HINT = "Install it with: pip install airbyte-agent-sdk[secrets-aws]"
_AWS_HINT = (
    "Local executable-bundle hydration currently supports AWS and GCP secret managers. "
    "Verify your AWS secret store configuration "
    "(AWS_SECRET_MANAGER_ACCESS_KEY_ID / AWS_SECRET_MANAGER_SECRET_ACCESS_KEY, "
    "optional AWS_SECRET_MANAGER_SESSION_TOKEN, and AWS_SECRET_MANAGER_REGION) "
    "and verify the secret coordinate exists in that AWS account and region. "
    "Execution was NOT sent to Airbyte Cloud."
)


def _is_secret_coordinate(value: Any) -> bool:
    return isinstance(value, str) and value.startswith(_SECRET_COORDINATE_PREFIX)


def _coordinate_secret_id(value: str) -> str:
    """Strip the `secret_coordinate::` prefix to get the AWS SM secret id."""
    return value.split("::", 1)[1]


def hydrate_source_config(
    source_config: dict[str, Any],
    *,
    credentials: AWSDataPlaneCredentials | None = None,
) -> dict[str, Any]:
    """Resolve `secret_coordinate::` values in *source_config* via AWS Secrets Manager.

    Walks nested dicts/lists and replaces every `secret_coordinate::<id>` string
    with the secret value fetched from AWS Secrets Manager, returning a fully
    hydrated config. Fails closed: any credential or fetch failure raises rather
    than falling back to hosted execution.

    Raises:
        ImportError: If boto3 is not installed (missing `secrets-aws` extra).
        ValueError: If AWS credentials are absent or a coordinate cannot be resolved.
    """
    credentials = credentials or resolve_aws_credentials()
    client = _build_secrets_manager_client(credentials)
    resolved_cache: dict[str, str] = {}

    def _resolve(value: Any) -> Any:
        if isinstance(value, dict):
            return {key: _resolve(inner) for key, inner in value.items()}
        if isinstance(value, list):
            return [_resolve(item) for item in value]
        if _is_secret_coordinate(value):
            secret_id = _coordinate_secret_id(value)
            if secret_id not in resolved_cache:
                resolved_cache[secret_id] = _fetch_secret(client, secret_id)
            return resolved_cache[secret_id]
        return value

    return _resolve(source_config)


def _build_secrets_manager_client(credentials: AWSDataPlaneCredentials) -> Any:
    # boto3 is an opt-in dependency (airbyte-agent-sdk[secrets-aws]) needed only on
    # the local hydration path, so it is imported lazily here to keep it off the
    # hosted execution path and out of the base install.
    try:
        import boto3
    except ImportError as exc:
        raise ImportError(f"boto3 is required to hydrate executable bundles from AWS Secrets Manager. {_INSTALL_HINT}") from exc

    client_kwargs: dict[str, Any] = {}
    if credentials.region_name:
        client_kwargs["region_name"] = credentials.region_name
    if credentials.has_explicit_keys:
        client_kwargs["aws_access_key_id"] = credentials.access_key_id
        client_kwargs["aws_secret_access_key"] = credentials.secret_access_key
        if credentials.session_token:
            client_kwargs["aws_session_token"] = credentials.session_token

    return boto3.client("secretsmanager", **client_kwargs)


def _fetch_secret(client: Any, secret_id: str) -> str:
    # botocore ships with boto3; import its exception types lazily alongside the
    # lazy boto3 client so the base install never needs botocore.
    from botocore.exceptions import BotoCoreError, ClientError, NoCredentialsError

    try:
        response = client.get_secret_value(SecretId=secret_id)
    except NoCredentialsError as exc:
        raise ValueError(
            "AWS credentials are required to hydrate the executable bundle in your data plane, " f"but none were found. {_AWS_HINT}"
        ) from exc
    except ClientError as exc:
        error_code = exc.response.get("Error", {}).get("Code")
        if error_code == "ResourceNotFoundException":
            raise ValueError(f"Secret coordinate '{secret_id}' was not found in AWS Secrets Manager. {_AWS_HINT}") from exc
        raise ValueError(f"Failed to resolve secret coordinate '{secret_id}' from AWS Secrets Manager. {_AWS_HINT} Details: {exc}") from exc
    except BotoCoreError as exc:
        raise ValueError(f"AWS Secrets Manager request failed while resolving '{secret_id}': {exc}") from exc

    secret_string = response.get("SecretString")
    if secret_string is None:
        raise ValueError(
            f"Secret coordinate '{secret_id}' resolved to a binary AWS Secrets Manager value. "
            "Store the connector credential as a plaintext SecretString."
        )

    try:
        parsed = json.loads(secret_string)
    except json.JSONDecodeError:
        return secret_string

    if isinstance(parsed, dict | list):
        raise ValueError(
            f"Secret coordinate '{secret_id}' resolved to a JSON AWS Secrets Manager value. "
            "Store the connector credential as a plaintext SecretString, not a JSON object."
        )
    return secret_string

